def determine_home_page(role, user_function):
    # application home page (will override Website Settings)
    home_page = "login"

    # website user home page (by Role)
    role_home_page = {
        "Admin": "admin_dashboard",
        "User": "user_dashboard"
    }

    # Website user home page (by function)
    def get_home_page(user_function):
        if user_function == "manage_users":
            return "users_management"
        elif user_function == "view_reports":
            return "reports_dashboard"
        else:
            return "default_home_page"

    # Check if role_home_page contains home page for the user's role
    if role in role_home_page:
        return role_home_page[role]
    # Check if get_website_user_home_page function is defined
    elif callable(get_home_page) and user_function:
        return get_home_page(user_function)
    # Return the default home page
    else:
        return home_page

# Test the function
print(determine_home_page("Admin", "manage_users"))  # Output: "users_management"
print(determine_home_page("User", "view_reports"))   # Output: "reports_dashboard"
print(determine_home_page("Guest", "explore_site"))  # Output: "login"
