class Cache:
    def __init__(self, function, limit=1000):
        self.function = function
        self.limit = limit
        self.store = {}

    def get(self, key):
        value = self.store.get(key)
        if value is None:
            value = self.function(key)
            self.set(key, value)
        return value

    def set(self, key, value):
        if len(self.store) >= self.limit:
            self.purge()
        self.store[key] = value

    def purge(self):
        if len(self.store) > self.limit:
            keys_to_remove = list(self.store.keys())[:len(self.store) - self.limit]
            for key in keys_to_remove:
                del self.store[key]
