```python
class PackageManager:
    def __init__(self):
        self.packages = {}

    def install(self, package_name, version=None):
        if package_name in self.packages:
            print(f"{package_name} is already installed")
            return

        if package_name not in packages:
            print(f"Error: {package_name} not found")
            return

        package_info = packages[package_name]
        if version is None:
            version = package_info["version"]

        print(f"Installing {package_name}-{version}")
        self.packages[package_name] = version

        for dependency in package_info["dependencies"]:
            self.install(dependency)

    def uninstall(self, package_name):
        if package_name not in self.packages:
            print(f"Error: {package_name} is not installed")
            return

        print(f"Uninstalling {package_name}")
        del self.packages[package_name]

        for pkg, info in packages.items():
            if package_name in info["dependencies"] and pkg not in self.packages:
                self.uninstall(pkg)

    def list_packages(self):
        return [(pkg, version) for pkg, version in self.packages.items()]

# Usage
pm = PackageManager()
pm.install("pyquil")
print(pm.list_packages())  # Output: [("pyquil", "2.1.0.dev0"), ("numpy", "1.19.5"), ("requests", "2.25.1"), ("urllib3", "1.26.4"), ("chardet", "4.0.0")]
pm.uninstall("pyquil")
print(pm.list_packages())  # Output: []
```

