from typing import List
import subprocess

def simulate_build(commands: List[List[str]], options: List[str]) -> int:
    parallel_jobs = 1
    verbose = False

    for opt in options:
        if opt.startswith("-j"):
            parallel_jobs = int(opt[2:])
        elif opt == "-v":
            verbose = True

    processes = []
    for cmd in commands:
        if verbose:
            print("Executing:", " ".join(cmd))
        process = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        processes.append(process)

    exit_codes = [p.wait() for p in processes]

    if all(code == 0 for code in exit_codes):
        return 0
    else:
        return 1
